// Construct an unexpected_type<int> and retrieve a mutable reference via value() &
{
    auto u = nonstd::make_unexpected( (int)(*FUZZ_PARAM(unsigned int) % 100000) );
    int &er = u.value();
    // Mutate to ensure reference is valid and writable
    er += (int)(*FUZZ_PARAM(unsigned int) % 5);
}
// Also try with a non-trivial error type
{
    std::string s = FUZZ_PARAM_STR();
    auto u = nonstd::make_unexpected(std::string(s));
    std::string &er2 = u.value();
    er2.append("_");
}
// Validation: value() is noexcept and requires lvalue; we hold u as lvalue and mutate the returned reference; no ownership to track.

// Swap two unexpected_type<std::string> to exercise ADL swappability constraints
std::string a = FUZZ_PARAM_STR();
std::string b = FUZZ_PARAM_STR();
a.resize(std::min<size_t>(a.size(), 64));
b.resize(std::min<size_t>(b.size(), 64));
nonstd::unexpected_type<std::string> ux = nonstd::make_unexpected(a);
nonstd::unexpected_type<std::string> uy = nonstd::make_unexpected(b);
ux.swap(uy);
// Validate basic property: after two swaps we should get original order back
swap(ux, uy);
// Validation: std::string is swappable/move-constructible; member and free swap both exercised; no outputs needed.

// Test equality of unexpected_type
{
    auto ux1 = nonstd::make_unexpected(std::string("e1"));
    auto ux2 = nonstd::make_unexpected(std::string("e1"));
    auto ux3 = nonstd::make_unexpected(std::string("e2"));
    volatile bool eq12 = (ux1 == ux2);
    volatile bool eq13 = (ux1 == ux3);
    (void)eq12; (void)eq13;
}
// Test equality of expected<T,E> when both hold values
{
    nonstd::expected<int, std::string> ex1 = 42;
    nonstd::expected<int, std::string> ex2 = 42;
    nonstd::expected<int, std::string> ex3 = 7;
    volatile bool v12 = (ex1 == ex2);
    volatile bool v13 = (ex1 == ex3);
    (void)v12; (void)v13;
}
// Test equality when both hold errors
{
    nonstd::expected<int, std::string> ex4 = nonstd::make_unexpected(std::string("e"));
    nonstd::expected<int, std::string> ex5 = nonstd::make_unexpected(std::string("e"));
    nonstd::expected<int, std::string> ex6 = nonstd::make_unexpected(std::string("f"));
    volatile bool e45 = (ex4 == ex5);
    volatile bool e46 = (ex4 == ex6);
    (void)e45; (void)e46;
}
// Test expected<T,E> == value
{
    nonstd::expected<int, std::string> ex7 = 123;
    volatile bool eqv = (ex7 == 123);
    (void)eqv;
}
// Validation: Covers equality across unexpected_type, expected value vs value, error vs error, and expected vs value.

// Free swap for unexpected_type<E>
{
    auto ux = nonstd::make_unexpected(std::string("A"));
    auto uy = nonstd::make_unexpected(std::string("B"));
    swap(ux, uy);
}
// Free swap for expected<T,E>
{
    nonstd::expected<int, std::string> ex1 = 11;
    nonstd::expected<int, std::string> ex2 = nonstd::make_unexpected(std::string("E"));
    swap(ex1, ex2);
}
// Validation: Both free-function swap customizations are exercised; constraints are satisfied with swappable/move-constructible types.

// Construct unexpected values from various types
{
    int e1 = (int)(*FUZZ_PARAM(unsigned int) % 100000);
    auto u1 = nonstd::make_unexpected(e1);
    (void)u1;
}
{
    std::string e2 = FUZZ_PARAM_STR();
    e2.resize(std::min<size_t>(e2.size(), 128));
    auto u2 = nonstd::make_unexpected(std::move(e2));
    (void)u2;
}
// Validation: Factory covers decay/copy/move construction paths; no persistent outputs required.

// Default-construct the void-specialized bad_expected_access base
nonstd::expected_lite::bad_expected_access<void> ex;
// Query what() for coverage
const char *msg = ex.what();
(void)msg;
// Validation: Default constructor is noexcept; what() returns a stable C-string.

// Create an error-state expected and force value() to throw, then query what()
try {
    nonstd::expected<int, std::string> ex = nonstd::make_unexpected(std::string("oops"));
    (void)ex.value();
} catch (nonstd::expected_lite::bad_expected_access<std::string> &be) {
    const char *w = be.what();
    (void)w;
}
// Validation: Path forces throw to reach what(); exception is handled locally.

// Trigger bad_expected_access<E> and access the stored error by reference
try {
    nonstd::expected<int, std::string> ex = nonstd::make_unexpected(std::string("err-detail"));
    (void)ex.value();
} catch (nonstd::expected_lite::bad_expected_access<std::string> &be) {
    std::string &er = be.error();
    // mutate to ensure writability
    er.push_back('!');
}
// Validation: Ensures exception path is taken and error() returns a mutable reference; no leaks or escapes.

// Use generic Error = std::string; expect bad_expected_access<std::string> to be thrown
try {
    nonstd::expected_lite::error_traits<std::string>::rethrow(std::string("gen-error"));
    FUZZ_BAIL(); // should not reach here when exceptions are enabled
} catch (nonstd::expected_lite::bad_expected_access<std::string> &) {
    // expected path
}
// Validation: Exercises generic rethrow mapping to bad_expected_access<Error>; contained entirely within try/catch.

// Create a non-empty exception_ptr and rethrow it
std::exception_ptr ep;
try {
    throw std::logic_error("lt");
} catch (...) {
    ep = std::current_exception();
}
try {
    nonstd::expected_lite::error_traits<std::exception_ptr>::rethrow(ep);
    FUZZ_BAIL();
} catch (...) {
    // expected: rethrow_exception dispatched
}
// Validation: Avoids empty exception_ptr by capturing first; rethrow is contained and handled.

// Rethrow a std::error_code as std::system_error
std::error_code ec = std::error_code(ENOENT, std::generic_category());
try {
    nonstd::expected_lite::error_traits<std::error_code>::rethrow(ec);
    FUZZ_BAIL();
} catch (const std::system_error &) {
    // expected
}
// Validation: Confirms mapping to system_error; exceptions are caught locally.

// Exercise member swap across different state combinations
{
    nonstd::expected<int, std::string> a = 1;
    nonstd::expected<int, std::string> b = nonstd::make_unexpected(std::string("e"));
    a.swap(b);
}
{
    nonstd::expected<int, std::string> c = 2;
    nonstd::expected<int, std::string> d = 3;
    c.swap(d);
}
{
    nonstd::expected<int, std::string> e = nonstd::make_unexpected(std::string("x"));
    nonstd::expected<int, std::string> f = nonstd::make_unexpected(std::string("y"));
    e.swap(f);
}
// Validation: Covers value↔error, value↔value, and error↔error paths; types satisfy swappability/move constraints.

// Define a simple struct to use operator-> on expected<T,E>
struct S { int x; int y; };
S s{ (int)(*FUZZ_PARAM(unsigned int) % 1000), (int)(*FUZZ_PARAM(unsigned int) % 1000) };
nonstd::expected<S, std::string> ex = s;
// Access members via operator-> when holding a value
int sum = ex->x + ex->y;
(void)sum;
// Validation: expected holds a value, satisfying precondition for operator->; no exceptions thrown.

// Use operator* to access contained value by const lvalue reference
nonstd::expected<int, std::string> ex = (int)(*FUZZ_PARAM(unsigned int) % 100000);
int v = *ex;
// Basic property check: dereferenced value equals conversion to int
FUZZ_ASSERT(v == (int)*ex, "operator* must yield the contained value");
// Validation: expected is in value state; operator* precondition is met.

// Check boolean state across both value and error cases
nonstd::expected<int, std::string> va = (int)(*FUZZ_PARAM(unsigned int) % 10);
nonstd::expected<int, std::string> er = nonstd::make_unexpected(std::string("bad"));
volatile bool ba = (bool)va;
volatile bool be = (bool)er;
(void)ba; (void)be;
// Validation: operator bool is noexcept and reflects state; both branches exercised.

// Exercise availability and usage of the in_place tag as a value (not a function)
// Some configurations alias nonstd::in_place to std::in_place and expose it as a constant, not a template function.
{
    // Simply reference the tag and take its address/sizeof to ensure ODR use
    auto const &tag = nonstd::in_place;
    (void)tag;
    volatile size_t s = sizeof(tag);
    (void)s;
}
// Validation: Uses the tag in a form compatible with implementations where in_place is a constant value, avoiding template call syntax.

// Exercise nonstd::in_place_type<T> as a tag constant (variable template), not a callable
{
    auto const &t1 = nonstd::in_place_type<int>;
    auto const &t2 = nonstd::in_place_type<std::string>;
    (void)t1; (void)t2;
    volatile size_t s = sizeof(t1) + sizeof(t2);
    (void)s;
}
// Validation: References the variable-template tags safely; no construction or calls performed.

// Exercise nonstd::in_place_index<K> as an index tag constant (variable template)
{
    auto const &i0 = nonstd::in_place_index<0>;
    auto const &i2 = nonstd::in_place_index<2>;
    (void)i0; (void)i2;
    volatile size_t s = sizeof(i0) + sizeof(i2);
    (void)s;
}
// Validation: References index tags without invoking call syntax, compatible across implementations.

// Inequality for unexpected_type
{
    auto ux1 = nonstd::make_unexpected(std::string("e1"));
    auto ux2 = nonstd::make_unexpected(std::string("e2"));
    volatile bool ne = (ux1 != ux2);
    (void)ne;
}
// Inequality for expected<T,E> vs expected<T,E>
{
    nonstd::expected<int, std::string> a = 7;
    nonstd::expected<int, std::string> b = 8;
    nonstd::expected<int, std::string> c = nonstd::make_unexpected(std::string("err"));
    volatile bool ab = (a != b); // value vs value
    volatile bool ac = (a != c); // value vs error (always true)
    (void)ab; (void)ac;
}
// Inequality for expected<T,E> vs value and value vs expected<T,E>
{
    nonstd::expected<int, std::string> v = (int)(*FUZZ_PARAM(unsigned int) % 10);
    volatile bool nv1 = (v != 12345); // likely true
    volatile bool nv2 = (12345 != v);
    (void)nv1; (void)nv2;
}
// Validation: Exercises all operator!= overload families by performing comparisons across states and with raw values.

// Check has_value() on both value and error states
{
    nonstd::expected<int, std::string> v = (int)(*FUZZ_PARAM(unsigned int) % 1000);
    nonstd::expected<int, std::string> e = nonstd::make_unexpected(std::string("err"));
    volatile bool hv = v.has_value();
    volatile bool he = e.has_value();
    (void)hv; (void)he;
}
// Validation: Noexcept state probe across both branches.

// Access value() in value state and handle error state throwing
{
    nonstd::expected<int, std::string> ok = 42;
    int x = ok.value();
    (void)x;
}
{
    nonstd::expected<int, std::string> er = nonstd::make_unexpected(std::string("boom"));
    try {
        (void)er.value();
        FUZZ_BAIL(); // should throw when no value
    } catch (...) {
        // expected: error_traits<E>::rethrow engaged
    }
}
// Validation: Exercises both success and error-throwing paths for value() const&.

// Access error() in error state; ensure assertion precondition is met by constructing error
{
    nonstd::expected<int, std::string> er = nonstd::make_unexpected(std::string("E"));
    std::string const &e = er.error();
    (void)e;
}
// Validation: Calls error() only on an error-state expected.

// Retrieve unexpected from error state and use its contained error reference
{
    nonstd::expected<int, std::string> er = nonstd::make_unexpected(std::string("UE"));
    auto u = er.get_unexpected();
    // touch the inner error via value() on unexpected_type
    std::string const &inner = u.value();
    (void)inner;
}
// Validation: get_unexpected() exercised; underlying error accessed read-only.

// Use exception_ptr as error type to exercise has_exception<Ex>()
{
    std::exception_ptr ep;
    try { throw std::runtime_error("rt"); } catch (...) { ep = std::current_exception(); }
    nonstd::expected<int, std::exception_ptr> er = nonstd::make_unexpected(ep);
    volatile bool hr = er.has_exception<std::runtime_error>();
    volatile bool hl = er.has_exception<std::logic_error>();
    (void)hr; (void)hl;
}
// Validation: Both positive/negative checks on stored exception type are covered.

// Verify value_or returns contained value or fallback converted to T
{
    nonstd::expected<int, std::string> v = 5;
    nonstd::expected<int, std::string> e = nonstd::make_unexpected(std::string("e"));
    int got_v = v.value_or(123);
    int got_e = e.value_or(123);
    FUZZ_ASSERT(got_v == 5, "value_or must return value when present");
