}
// Validation: Exercises both branches; uses convertible fallback type.

// error() only valid when holding an error
{
    nonstd::expected<void, std::string> e = nonstd::make_unexpected(std::string("E"));
    std::string const &er = e.error();
    (void)er;
}
// Validation: Called under correct precondition.

// get_unexpected() returns unexpected_type<E> with stored error
{
    nonstd::expected<void, std::string> e = nonstd::make_unexpected(std::string("GE"));
    auto u = e.get_unexpected();
    std::string const &er = u.value();
    (void)er;
}
// Validation: Retrieves unexpected wrapper and touches contained error.

// Use exception_ptr error type to drive has_exception<Ex>() for void specialization
{
    std::exception_ptr ep;
    try { throw std::logic_error("le"); } catch (...) { ep = std::current_exception(); }
    nonstd::expected<void, std::exception_ptr> e = nonstd::make_unexpected(ep);
    volatile bool hl = e.has_exception<std::logic_error>();
    volatile bool hr = e.has_exception<std::runtime_error>();
    (void)hl; (void)hr;
}
// Validation: Positive/negative matches on exception type.

// Transition error-state expected<void,E> to value state via emplace()
{
    nonstd::expected<void, std::string> e = nonstd::make_unexpected(std::string("err"));
    e.emplace();
    FUZZ_ASSERT((bool)e, "emplace() should yield value state for expected<void,E>");
}
// Validation: State transition verified.

// Emplace a new value into expected<T,E>, satisfying the nothrow-constructible constraint
{
    // Use T = int (trivially nothrow-constructible from int) and E = std::string
    nonstd::expected<int, std::string> ex = nonstd::make_unexpected(std::string("err"));
    int v = (int)(*FUZZ_PARAM(unsigned int) % 100000);
    int &ref = ex.emplace(v); // should be noexcept-constructible for int
    // Validate: emplace returns reference to contained value
    FUZZ_ASSERT(&ref == &*ex, "emplace should return reference to contained value");
}
// Validation: Transitions from error to value state via emplace(Args...) using int which meets noexcept construction.

// Swap expected<void,E> instances across different states without relying on helper factories
